const byId = new Map(CHAT_ANIMATIONS.map((item) => [item.id, item]));

export const animationById = (id) => byId.get(String(id || '')) || null;

export const FEATURED_ANIMATIONS = ["1027548","10077","42289","82933","51104","92086","850","1518211","83611","88250","1510800","1505654","1510790","137369","17979","1526290"].map((id) => byId.get(id)).filter(Boolean);

export const animationMatches = (item, query) => emojiMatches({ char: '', q: `${item.name} ${item.q}` }, query);

export const readRecentAnimationIds = () => {
  try {
    const raw = JSON.parse(window.localStorage.getItem(RECENT_KEY) || '[]');
    if (!Array.isArray(raw)) return [];
    return raw.filter((id) => typeof id === 'string' && byId.has(id)).slice(0, RECENT_MAX);
  } catch (_err) {
    return [];
  }
};

export const rememberAnimation = (id) => {
  const next = [id, ...readRecentAnimationIds().filter((item) => item !== id)].slice(0, RECENT_MAX);
  window.localStorage.setItem(RECENT_KEY, JSON.stringify(next));
  return next;
};
